import{_ as a,c as t,o as l,ag as r}from"./chunks/framework.DPDPlp3K.js";const _=JSON.parse('{"title":"错题本分析规范（用户发回导出文本后）","description":"","frontmatter":{},"headers":[],"relativePath":"public/skills/exam-sprint-workflow/references/wrong-book-analysis.md","filePath":"public/skills/exam-sprint-workflow/references/wrong-book-analysis.md"}'),e={name:"public/skills/exam-sprint-workflow/references/wrong-book-analysis.md"};function s(n,o,i,u,c,d){return l(),t("div",null,o[0]||(o[0]=[r('<h1 id="错题本分析规范-用户发回导出文本后" tabindex="-1">错题本分析规范（用户发回导出文本后） <a class="header-anchor" href="#错题本分析规范-用户发回导出文本后" aria-label="Permalink to &quot;错题本分析规范（用户发回导出文本后）&quot;">​</a></h1><p>用户从网页一键导出的错题本是纯文本：顶部统计（各模块错题数、考点分布）+ 逐题明细（题号、题干、选项、我的答案、正确答案、考点、来源）。收到后按本规范输出分析。</p><h2 id="分析步骤" tabindex="-1">分析步骤 <a class="header-anchor" href="#分析步骤" aria-label="Permalink to &quot;分析步骤&quot;">​</a></h2><ol><li><strong>解析统计</strong>：错题总数、按模块分布、按考点标签分布（程序化统计，不心数）。</li><li><strong>聚类归因</strong>：把考点标签归并为知识族（如&quot;反义疑问句+倒装+强调句&quot;→句法类），按族统计错误率 = 该族错题数 / 该族已做题数。</li><li><strong>区分错因</strong>：同一考点反复错（≥2 次）= 知识漏洞；只错一次且集中在某套卷 = 可能是粗心/疲劳；主观题自评&quot;部分正确&quot;居多 = 输出能力问题不是知识问题。</li><li><strong>排序</strong>：提分性价比 = 错误率 × 该考点在试卷中的分值权重。排前三的进&quot;死磕清单&quot;。</li></ol><h2 id="输出格式-直接回复用户-无需建文档" tabindex="-1">输出格式（直接回复用户，无需建文档） <a class="header-anchor" href="#输出格式-直接回复用户-无需建文档" aria-label="Permalink to &quot;输出格式（直接回复用户，无需建文档）&quot;">​</a></h2><ol><li><strong>总体判断</strong>（2-3 句）：错题规模、最薄弱的 2-3 个知识族、离合格线的差距评估</li><li><strong>薄弱清单表</strong>：考点族 | 错误率 | 试卷权重 | 判定（知识漏洞/粗心/输出问题）</li><li><strong>补弱任务</strong>：每个死磕点给 1 个具体任务（材料+时长+验收标准），挂到未来 3-5 天的对应任务位</li><li><strong>计划调整</strong>：对照 plan_data.json 的 thresholds 和 adjustment_rules，说明哪些天怎么改；如需改页面则原地更新应用</li></ol><h2 id="调参铁律" tabindex="-1">调参铁律 <a class="header-anchor" href="#调参铁律" aria-label="Permalink to &quot;调参铁律&quot;">​</a></h2><ul><li>连续两次错题分析同一考点族仍无改善 → 按调整规则降载：换更基础的材料重学，不再加题量。</li><li>分析结论必须同步落回计划：要么改 plan_data.json 并更新页面，要么明确说&quot;计划不用动，原因 X&quot;——不能只给分析不闭环。</li><li>用户只发了部分错题时，注明本次样本量，结论按样本量打折表述。</li></ul>',8)]))}const g=a(e,[["render",s]]);export{_ as __pageData,g as default};
